import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type { SavedGuidance } from '../../types/guidance';
import { isRemoteProfileProvider } from '../../types/design-profile';
import type { SourceSyncState } from '../../types/source-sync';
import { guidanceSyncChecks } from './GuidanceSync';
import { reconnectRequiredMessage } from './ProfileImports';
import { referenceSyncChecks } from './ReferenceSync';

const IN_PROGRESS_JOB_STATES = new Set(['pending', 'paused']);

export const contextSyncStates = (
  documents: readonly SavedGuidance[],
  now: number,
): SourceSyncState[] => {
  const due = new Set(
    guidanceSyncChecks(documents)
      .filter((check) => check.dueAt <= now)
      .map((check) => check.sourceId),
  );
  return documents.flatMap((document) =>
    document.origin && document.sync && document.syncMode
      ? [
          {
            family: 'context' as const,
            sourceId: document.id,
            title: document.title,
            syncMode: document.syncMode,
            lastSyncedAt: document.sync.syncedAt,
            checkedAt: document.sync.checkedAt,
            lastError: document.sync.error ?? null,
            isDue: due.has(document.id),
            isInProgress: false,
            needsReconnect: false,
          },
        ]
      : [],
  );
};

export const referenceSyncStates = (
  records: ProfileRecords,
  now: number,
): SourceSyncState[] => {
  const due = new Set(
    referenceSyncChecks(records)
      .filter((check) => check.dueAt <= now)
      .map((check) => check.sourceId),
  );
  const jobs = records.jobs();
  return records.sources().flatMap((source) => {
    const sourceJobs = jobs.filter((job) => job.sourceId === source.id);
    const last = sourceJobs[sourceJobs.length - 1];
    if (!isRemoteProfileProvider(source.provider) || !last) return [];
    const completed = sourceJobs.filter((job) => job.state === 'complete');
    const isFailed = last?.state === 'failed';
    return [
      {
        family: 'references' as const,
        sourceId: source.id,
        title: source.title,
        syncMode: source.syncMode,
        lastSyncedAt: completed[completed.length - 1]?.updatedAt ?? null,
        checkedAt: last.updatedAt,
        lastError: isFailed ? (last.error ?? null) : null,
        isDue: due.has(source.id),
        isInProgress: sourceJobs.some((job) =>
          IN_PROGRESS_JOB_STATES.has(job.state),
        ),
        needsReconnect:
          isFailed && last.error === reconnectRequiredMessage(source.provider),
      },
    ];
  });
};
